// t01: ledger, its format, folios and the mechanics of posting (To / By, compound entries, opening entries).
// Imagined firms; every ledger is generated by acc.mjs post() from balanced journal entries and asserted.
import { mcq, ar, tf, fb, short, long } from './lib.mjs';
import { same, check, sum, inr, rs, mdTable, post, postD, jrnl, showL, postedOnly, lmd, acct, openingsFrom, E1 } from './fig.mjs';
import { QQ } from './qq.mjs';

// ================================================================ multiple choice
QQ('m_ledger_meaning', mcq({
  t: 1, d: 1, c: 'recall',
  stem: 'Gudiyatham Looms, an imagined firm, wants one book in which every item, such as cash, sales and each customer, has an account of its own so that the total effect and balance of each can be seen at a glance. That book is the',
  opts: ['ledger', 'journal', 'cash book', 'trial balance'],
  sol: 'The ledger classifies the entries of the journal account by account. The journal records transactions in date order, and a trial balance only lists balances already found.',
}));
const PD = [E1([['Ranjit Traders A/c', 18000]], [['Sales A/c', 18000]], 'Being goods sold on credit to Ranjit Traders')];
const PDL = post(PD);
check(PDL['Ranjit Traders A/c'].rows[0][0] === 'To Sales A/c', 'posting of Ranjit Traders debit');
check(PDL['Sales A/c'].rows[0][2] === 'By Ranjit Traders A/c', 'posting of Sales credit');
QQ('m_post_debit', mcq({
  t: 1, d: 2, c: 'understanding',
  stem: 'Tonk Spices, an imagined firm, sold goods on credit to Ranjit Traders for ₹18,000. When the entry is posted from the journal, the debit side of Ranjit Traders A/c in the ledger carries the particulars',
  opts: ['To Sales A/c', 'By Sales A/c', 'To Ranjit Traders A/c', 'By Tonk Spices A/c'],
  sol: 'On the debit side the word To is used and the other account of the entry, Sales, is named. By Sales A/c is the wording of the credit side, an account is never named in its own page, and the firm itself does not appear as an account.',
}));
QQ('m_jf', mcq({
  t: 1, d: 1, c: 'recall',
  stem: 'While posting an entry to the ledger of Palwal Bricks, an imagined firm, the clerk writes the page number of the journal on which the entry stands in a column of the ledger account. That column is headed',
  opts: ['J.F. (journal folio)', 'L.F. (ledger folio)', 'V.No. (voucher number)', 'Remarks'],
  sol: 'The journal page is noted in the ledger under J.F. The L.F. column belongs to the journal, where it holds the page of the ledger account, and a voucher number points to a source document.',
}));
QQ('m_folio', mcq({
  t: 1, d: 2, c: 'understanding',
  stem: 'In the journal of Bomdila Woolens, an imagined firm, the L.F. column against each account is filled in',
  opts: ['after posting, with the page number of that account in the ledger', 'while recording the entry, with the page number of the journal itself', 'only for cash entries, with the number of the voucher', 'at the year end, with the balance of the account'],
  sol: 'The ledger folio is the cross-reference from the journal to the ledger, so it can be entered only once the entry has been posted. It is not the journal page, a voucher number or a balance.',
}));
const DC = [E1([['Machine A/c', 90000]], [['Cash A/c', 50000], ['Eastern Tools A/c', 40000]], 'Being machine bought, part paid in cash and the rest owed to Eastern Tools')];
const DCL = post(DC);
check(DCL['Machine A/c'].rows[0][0] === 'To Sundries', 'compound posting of Machine A/c');
check(DCL['Cash A/c'].rows[0][2] === 'By Machine A/c', 'compound posting of Cash A/c');
QQ('m_compound_post', mcq({
  t: 1, d: 3, c: 'application',
  stem: 'Dhule Cycles, an imagined firm, buys a machine for ₹90,000, pays ₹50,000 in cash and owes the rest to Eastern Tools, all in one journal entry. When the entry is posted, the particulars on the debit side of Machine A/c read',
  opts: ['To Sundries', 'To Cash A/c', 'To Eastern Tools A/c', 'By Sundries'],
  sol: 'The machine is debited and two accounts are credited, so the other side is described by the single word Sundries, with To for a debit. Naming only Cash or only Eastern Tools hides part of the entry, and By belongs to the credit side.',
}));
QQ('m_opening_entry', mcq({
  t: 1, d: 1, c: 'recall',
  stem: 'At the start of the new year, Kollam Cashews, an imagined firm, passes one journal entry that debits its assets and credits its liabilities and capital so that the new books begin with the old balances. This entry is called the',
  opts: ['opening entry', 'closing entry', 'adjusting entry', 'rectifying entry'],
  sol: 'An entry that brings the balances of the old books into the new ones is an opening entry. A closing entry ends the period, an adjusting entry corrects the figures of the period for accruals, and a rectifying entry mends an error.',
}));
QQ('m_ledger_benefit', mcq({
  t: 1, d: 2, c: 'understanding',
  stem: 'Sivasagar Tea Stall, an imagined business, finds that the dealings with one customer are scattered over many pages of its journal. Which advantage of the ledger removes this difficulty?',
  opts: ['All transactions of one account are brought together, so its balance is easily found', 'Transactions are recorded in the order in which they happen', 'Every entry is supported by a source document', 'Profit is found by the ledger without any other statement'],
  sol: 'Grouping the entries account by account is the work of the ledger. Date order and source documents belong to the journal and its vouchers, and profit needs the final accounts.',
}));
QQ('m_running_balance', mcq({
  t: 1, d: 2, c: 'understanding',
  stem: 'Mandya Jaggery, an imagined firm, keeps its customer accounts in a form with columns for date, particulars, folio, debit, credit and a balance that is worked out after every entry. This form of the ledger account is the',
  opts: ['running balance form', 'T-form', 'columnar journal', 'subsidiary journal'],
  sol: 'A balance column worked out after each entry is the running balance form, convenient for customers and suppliers. The T-form has two sides and is balanced only when the period is closed, and the other two are books of original entry.',
}));
QQ('m_chk_posting', mcq({
  t: 1, d: 1, c: 'application',
  stem: 'Nandurbar Hardware, an imagined shop, paid ₹4,500 in cash as rent. After the entry is posted, the Rent A/c shows',
  opts: ['To Cash A/c ₹4,500 on the debit side', 'By Cash A/c ₹4,500 on the credit side', 'To Rent A/c ₹4,500 on the debit side', 'By Cash A/c ₹4,500 on the debit side'],
  sol: 'Rent is an expense, so it is debited, and the entry names the other account, Cash, with To. Placing the amount on the credit side, naming Rent on its own page, or using By on the debit side breaks the rule of posting.',
}));

// ================================================================ assertion-reason
QQ('ar_post_after_journal', ar({
  t: 1, d: 3, c: 'analysis', verdict: 'both-true-explains',
  a: 'In the books of an imagined firm, the ledger is written up from the journal and not the other way round.',
  r: 'Each transaction is first recorded in the journal in date order, and the ledger then collects the entries account by account.',
  sol: 'Both statements are true, and the reason describes exactly the order of work that makes the ledger a secondary book written from the journal.',
}));
QQ('ar_folio', ar({
  t: 1, d: 3, c: 'analysis', verdict: 'both-true-not-explains',
  a: 'Folio numbers link each account in the journal with its page in the ledger.',
  r: 'The ledger is one of the principal books of account.',
  sol: 'Both statements are true, but being a principal book says nothing about why a cross-reference is needed. Folios are there so that any entry can be traced from one book to the other.',
}));

// ================================================================ true-false, fill-blank
QQ('tf_ledger_book', tf({
  t: 1, d: 1, c: 'understanding', ans: false,
  stem: 'Jorhat Books, an imagined shop, treats its ledger as the book of original entry, in which every transaction is first recorded in date order.',
  sol: 'It is the journal that is the book of original entry. The ledger is written afterwards, from the journal.',
}));
QQ('fb_chk_folio', fb({
  t: 1, d: 1, c: 'recall',
  stem: 'The page number of the ledger account written in the journal is the ______ folio (L.F.), and the page number of the journal written in the ledger is the ______ folio (J.F.).',
  acc: [['ledger'], ['journal']],
  sol: 'The ledger folio goes in the journal and the journal folio goes in the ledger.',
}));

// ================================================================ short answer, 2 marks
QQ('s2_ledger_meaning', short({
  t: 1, d: 1, c: 'recall', marks: 2,
  stem: 'What is a ledger? State one way in which it helps a firm.',
  model: 'The **ledger** is the principal book of accounts in which the transactions already recorded in the journal are classified and posted under separate heads, each head having an account of its own.\n\nOne help: it brings together everything relating to one account, so the balance of that account (for example what a customer owes) can be found at once and the trial balance can be prepared from it.',
  sol: 'Meaning, then one help.',
  scheme: [['Meaning: principal book with an account for each head, posted from the journal', 1], ['One benefit stated', 1]],
}));
QQ('s2_folios', short({
  t: 1, d: 2, c: 'understanding', marks: 2,
  stem: 'Distinguish between the ledger folio and the journal folio.',
  model: '**Ledger folio (L.F.):** the page number of the ledger account, written in the journal against the account, after the entry has been posted.\n\n**Journal folio (J.F.):** the page number of the journal, written in the ledger account against the posted item, so that the original entry can be traced.',
  sol: 'Where each is written and what it points to.',
  scheme: [['Ledger folio: ledger page, written in the journal', 1], ['Journal folio: journal page, written in the ledger', 1]],
}));
QQ('s2_opening_entry', short({
  t: 1, d: 2, c: 'understanding', marks: 2,
  stem: 'Eluru Dairy, an imagined firm, starts its new books on 1 April 2027 with cash ₹30,000, stock ₹50,000 and a creditor ₹20,000. Pass the opening entry and say how capital is found.',
  model: `${jrnl([{ date: '1 Apr 2027', dr: [['Cash A/c', 30000], ['Stock A/c', 50000]], cr: [['Creditors A/c', 20000], ['Capital A/c', 60000]], note: 'Being assets, liability and capital brought forward' }], { 'Cash A/c': 1, 'Stock A/c': 2, 'Creditors A/c': 3, 'Capital A/c': 4 }).md}\n\nCapital = assets − liabilities = ${inr(80000)} − ${inr(20000)} = ${rs(60000)}.`,
  sol: 'Debit assets, credit liabilities, and capital is the balancing figure.',
  scheme: [['Assets debited with their amounts', 1], ['Creditors and capital credited, capital found as ₹60,000', 1]],
}));

// ================================================================ short answer, 3 marks
const BH = [
  E1([['Purchases A/c', 26000]], [['Kamal Hides A/c', 26000]], 'Being goods bought on credit from Kamal Hides', '4 Jun'),
  E1([['Kamal Hides A/c', 20000]], [['Cash A/c', 20000]], 'Being cash paid to Kamal Hides', '11 Jun'),
];
const BHL = postD(BH, { openings: { 'Cash A/c': { side: 'dr', amount: 35000 } } });
same(BHL['Kamal Hides A/c'].balance, -6000, 'Kamal Hides balance');
same(BHL['Cash A/c'].balance, 15000, 'Barmer cash balance');
QQ('s3_posting_two', short({
  t: 1, d: 3, c: 'application', marks: 3,
  stem: 'Barmer Leather, an imagined firm, has an opening cash balance of ₹35,000 on 1 June 2027. Its journal shows (i) 4 June: goods bought on credit from Kamal Hides for ₹26,000; (ii) 11 June: cash paid to Kamal Hides ₹20,000. Post the two entries to the ledger accounts of Purchases, Kamal Hides and Cash, and balance the accounts of Kamal Hides and Cash.',
  model: `${postedOnly(BHL['Purchases A/c']).md}\n\n${lmd(BHL['Kamal Hides A/c'])}\n\n${lmd(BHL['Cash A/c'])}\n\nKamal Hides A/c has a credit balance of ${rs(6000)} (the amount still owed) and Cash A/c a debit balance of ${rs(15000)} (35,000 − 20,000).`,
  sol: 'Debit side To the other account, credit side By the other account, then balance.',
  scheme: [['Purchases A/c debited: To Kamal Hides A/c with the amount', 1], ['Kamal Hides A/c: debit 20,000 and credit 26,000 with correct particulars', 1], ['Cash A/c with the opening balance and the payment, and both balances correct', 1]],
}));
const RB = { open: 12000, sale: 8000, recd: 15000, ret: 2000 };
let rbBal = RB.open;
const rbRows = [['1 Mar', 'Balance b/d', inr(RB.open), '', `${inr(rbBal)} Dr`]];
rbBal += RB.sale; rbRows.push(['6 Mar', 'To Sales A/c', inr(RB.sale), '', `${inr(rbBal)} Dr`]);
rbBal -= RB.recd; rbRows.push(['14 Mar', 'By Cash A/c', '', inr(RB.recd), `${inr(rbBal)} Dr`]);
rbBal -= RB.ret; rbRows.push(['22 Mar', 'By Sales Return A/c', '', inr(RB.ret), `${inr(rbBal)} Dr`]);
same(rbBal, 3000, 'running balance');
QQ('s3_running_form', short({
  t: 1, d: 3, c: 'application', marks: 3,
  stem: 'Ladakh Dry Fruits, an imagined firm, shows Suresh Mart, a customer, with a debit balance of ₹12,000 on 1 March 2027. On 6 March it sold him goods for ₹8,000, on 14 March he paid ₹15,000 in cash and on 22 March he returned goods worth ₹2,000. Write his account in the running balance form.',
  model: `${mdTable(['Date', 'Particulars', 'Dr (₹)', 'Cr (₹)', 'Balance (₹)'], rbRows)}\n\nBalance after each line: ${inr(RB.open)} + ${inr(RB.sale)} = ${inr(RB.open + RB.sale)}; − ${inr(RB.recd)} = ${inr(RB.open + RB.sale - RB.recd)}; − ${inr(RB.ret)} = ${rs(rbBal)} Dr.`,
  sol: 'Sale to the debit column, receipt and return to the credit column, balance recomputed each line.',
  scheme: [['Format with date, particulars, Dr, Cr and balance columns', 1], ['Sale on the debit side, receipt and return on the credit side', 1], ['Balance after each line, closing ₹3,000 Dr', 1]],
}));
const OG = [E1([['Wages A/c', 6000], ['Salaries A/c', 14000]], [['Cash A/c', 20000]], 'Being wages and salaries paid in cash', '30 Jun 2027')];
const OGJ = jrnl(OG, { 'Wages A/c': 7, 'Salaries A/c': 8, 'Cash A/c': 1 });
const OGL = postD(OG, { openings: { 'Cash A/c': { side: 'dr', amount: 50000 } } });
same(OGL['Cash A/c'].balance, 30000, 'Ongole cash balance');
check(OGL['Cash A/c'].rows[0][2] === '30 Jun 2027 By Sundries (J.F. 1)', 'Ongole cash posting wording');
QQ('s3_compound_posting', short({
  t: 1, d: 3, c: 'application', marks: 3,
  stem: 'On 30 June 2027 Ongole Granite, an imagined firm, paid wages of ₹6,000 and salaries of ₹14,000 in cash and passed one entry for both. Cash A/c had a debit balance of ₹50,000 at the start. Show the journal entry and post it to the Wages, Salaries and Cash accounts.',
  model: `${OGJ.md}\n\n${postedOnly(OGL['Wages A/c']).md}\n\n${postedOnly(OGL['Salaries A/c']).md}\n\n${lmd(OGL['Cash A/c'])}\n\nCash A/c shows By Sundries because two accounts are on the other side of the entry.`,
  sol: 'One compound journal entry, then each account posted with the other side named.',
  scheme: [['Compound entry: Wages and Salaries debited, Cash credited, with narration', 1], ['Wages A/c and Salaries A/c: To Cash A/c on the debit side', 1], ['Cash A/c: By Sundries on the credit side with the balance ₹30,000 c/d', 1]],
}));

// ================================================================ long answer, 5 marks
QQ('l5_diff', long({
  t: 1, d: 2, c: 'understanding', marks: 5,
  stem: 'Distinguish between the journal and the ledger on any five points.',
  model: mdTable(['Basis', 'Journal', 'Ledger'], [
    ['Nature', 'Book of original (prime) entry', 'Book of secondary entry, written from the journal'],
    ['Order of entry', 'Transactions in date order', 'Transactions grouped account by account'],
    ['Stage', 'First stage of recording', 'Second stage, after the journal'],
    ['Basis', 'Source documents (vouchers, bills)', 'Journal entries'],
    ['Narration', 'Given under every entry', 'Not given; only the other account is named'],
    ['Balance', 'No balance of an account is found', 'Every account is balanced'],
    ['Format', 'Date, particulars, L.F., debit and credit columns', 'Two-sided account with date, particulars, J.F. and amount'],
  ]) + '\n\nAny five rows earn full marks.',
  sol: 'One mark for each correct point of difference, with both sides stated.',
  scheme: [['First point of difference stated for both books', 1], ['Second point stated for both books', 1], ['Third point stated for both books', 1], ['Fourth point stated for both books', 1], ['Fifth point stated for both books', 1]],
}));
const SS = {
  opening: { date: '1 Oct 2027', dr: [['Cash A/c', 60000], ['Stock A/c', 90000], ['Furniture A/c', 40000]], cr: [['Jyoti Weavers A/c', 30000], ['Capital A/c', 160000]], note: 'Being the opening balances brought forward' },
  txn: [
    E1([['Purchases A/c', 45000]], [['Jyoti Weavers A/c', 45000]], 'Being goods bought on credit from Jyoti Weavers', '3 Oct'),
    E1([['Cash A/c', 38000]], [['Sales A/c', 38000]], 'Being goods sold for cash', '7 Oct'),
    E1([['Meena Boutique A/c', 27000]], [['Sales A/c', 27000]], 'Being goods sold on credit to Meena Boutique', '12 Oct'),
    E1([['Jyoti Weavers A/c', 50000]], [['Cash A/c', 50000]], 'Being cash paid to Jyoti Weavers', '18 Oct'),
    E1([['Cash A/c', 20000]], [['Meena Boutique A/c', 20000]], 'Being cash received from Meena Boutique', '25 Oct'),
    E1([['Rent A/c', 6000], ['Salaries A/c', 9000]], [['Cash A/c', 15000]], 'Being rent and salaries paid in cash', '29 Oct'),
  ],
};
const SSL = postD(SS.txn, { openings: openingsFrom(SS.opening) });
same(SSL['Cash A/c'].balance, 53000, 'Sambalpur cash balance');
same(SSL['Jyoti Weavers A/c'].balance, -25000, 'Jyoti Weavers balance');
same(SSL['Meena Boutique A/c'].balance, 7000, 'Meena Boutique balance');
const ssOpt = { close: '31 Oct 2027', open: '1 Nov 2027', openingDate: '1 Oct 2027' };
QQ('l5_post_ledgers', long({
  t: [1, 2], d: 3, c: 'application', marks: 5,
  stem: `Sambalpur Sarees, an imagined firm, opened its new books on 1 October 2027 with cash ₹60,000, stock ₹90,000 and furniture ₹40,000, a creditor Jyoti Weavers ₹30,000 and capital ₹1,60,000. Its journal for October 2027 shows: 3 Oct goods bought on credit from Jyoti Weavers ₹45,000; 7 Oct cash sales ₹38,000; 12 Oct goods sold on credit to Meena Boutique ₹27,000; 18 Oct cash paid to Jyoti Weavers ₹50,000; 25 Oct cash received from Meena Boutique ₹20,000; 29 Oct rent ₹6,000 and salaries ₹9,000 paid in cash (one entry). Post the entries to the accounts of (a) Cash [2], (b) Jyoti Weavers [1], (c) Meena Boutique [1], balance them on 31 October 2027, and (d) state the nature of each closing balance [1].`,
  model: `**(a)**\n\n${acct(SSL['Cash A/c'], ssOpt)}\n\n**(b)**\n\n${acct(SSL['Jyoti Weavers A/c'], ssOpt)}\n\n**(c)**\n\n${acct(SSL['Meena Boutique A/c'], ssOpt)}\n\n**(d)** Cash A/c: debit balance ${rs(53000)}, an asset (cash in hand). Jyoti Weavers A/c: credit balance ${rs(25000)}, a liability (amount payable). Meena Boutique A/c: debit balance ${rs(7000)}, an asset (amount receivable).`,
  sol: 'Opening balances come in as b/d, each entry names the other account, and each account is balanced.',
  scheme: [['Cash A/c: opening balance, receipts and payments on the correct sides', 1], ['Cash A/c: balance ₹53,000 c/d and b/d', 1], ['Jyoti Weavers A/c with its opening credit balance, the purchase and the payment, balance ₹25,000 Cr', 1], ['Meena Boutique A/c with the sale and the receipt, balance ₹7,000 Dr', 1], ['Nature of the three balances stated', 1]],
}));
void sum; void showL; void SS;
